// 採用プールの名前 -> 絵のキー（見た目は名前ごとに固定）
export const POOL_PORTRAIT_KEYS = {
  "冬木 玲": "p01",
  "夏目 湊": "p02",
  "秋山 栞": "p03",
  "春日 陽": "p04",
  "星野 律": "p05",
  "月島 凪": "p06",
  "雪代 紬": "p07",
  "雨宮 慧": "p08",
  "風間 樹": "p09",
  "水瀬 凛": "p10",
  "朝倉 葵": "p11",
  "夕霧 蓮": "p12",
  "東雲 梓": "p13",
  "深町 駿": "p14",
  "浅野 遥": "p15",
  "白鳥 紗": "p16",
  "高瀬 航": "p17",
  "瀬戸 泉": "p18",
  "広瀬 渉": "p19",
  "青柳 翠": "p20"
};

// 社員オブジェクト（id または name を持つ）から絵のキーの土台を返す。絵が無い場合は null。
export function portraitBaseOf(person) {
  if (!person) return null;
  if (person.id && /^emp-[1-5]$/.test(person.id)) return person.id.replace("-", "");
  if (person.name && POOL_PORTRAIT_KEYS[person.name]) return POOL_PORTRAIT_KEYS[person.name];
  return null;
}

// mode: "white" | "black" / expr: "normal" | "smile" | "sad"
export function portraitUri(person, mode, expr) {
  const base = portraitBaseOf(person);
  if (!base) return null;
  return PORTRAITS[`${base}-${mode === "black" ? "black" : "white"}-${expr || "normal"}`] || null;
}
